template <typename T>
T modular_inverse(T a, T m) {
  T u = 0, v = 1;
  while (a != 0) {
    T t = m / a;
    m -= t * a; swap(a, m);
    u -= t * v; swap(u, v);
  }
  assert(m == 1);
  return u;
}

template <typename T>
class ModularType {
 public:
  using Type = typename decay<decltype(T::value)>::type;

  ModularType() : val() {}
  template <typename U>
  ModularType(const U& x) {
    val = normalize(x);
  }

  static Type normalize(const U& x) {
    Type v;
    if (-mod() <= x && x < mod()) v = static_cast<Type>(x);
    else v = static_cast<Type>(x % mod());
    if (v < 0) v += mod();
    return v;
  }

  const Type& get() const { return val; }
  explicit operator Type() const { return val; }
  static constexpr Type mod() { return T::value; }

  ModularType& operator+=(const ModularType& other) {
    if ((val += other.val) >= mod()) val -= mod();
    return *this;
  }
  ModularType& operator-=(const ModularType& other) {
    if ((val -= other.val) < 0) val += mod();
    return *this;
  }
  template <typename U> ModularType& operator+=(const U& other) { return *this += ModularType(other); }
  template <typename U> ModularType& operator-=(const U& other) { return *this -= ModularType(other); }
  ModularType& operator++() { return *this += 1; }
  ModularType& operator--() { return *this -= 1; }
  ModularType operator++(int) { ModularType tmp(*this); *this += 1; return tmp; }
  ModularType operator--(int) { ModularType tmp(*this); *this -= 1; return tmp; }
  ModularType operator-() const { return ModularType(-val); }

  template <typename U = T>
  typename enable_if<is_same<typename ModularType<U>::Type, int>::value, ModularType>::type& operator*=(const ModularType& rhs) {
#ifdef _WIN32
    uint64_t x = static_cast<int64_t>(val) * static_cast<int64_t>(rhs.val);
    uint32_t xh = static_cast<uint32_t>(x >> 32), xl = static_cast<uint32_t>(x), d, m;
    asm(
      "divl %4; \n\t"
      : "=a" (d), "=d" (m)
      : "d" (xh), "a" (xl), "r" (mod())
    );
    val = m;
#else
    val = normalize(static_cast<int64_t>(val) * static_cast<int64_t>(rhs.val));
#endif
    return *this;
  }
  template <typename U = T>
  typename enable_if<is_same<typename ModularType<U>::Type, int64_t>::value, ModularType>::type& operator*=(const ModularType& rhs) {
    int64_t q = static_cast<int64_t>(static_cast<long double>(val) * rhs.val / mod());
    val = normalize(val * rhs.val - q * mod());
    return *this;
  }
  template <typename U = T>
  typename enable_if<!is_integral<typename ModularType<U>::Type>::value, ModularType>::type& operator*=(const ModularType& rhs) {
    val = normalize(val * rhs.val);
    return *this;
  }

  ModularType& operator/=(const ModularType& other) { return *this *= modular_inverse(other.val, mod()); }

  friend bool operator==(const ModularType& lhs, const ModularType& rhs) { return lhs.val == rhs.val; }
  friend bool operator<(const ModularType& lhs, const ModularType& rhs) { return lhs.val < rhs.val; }

  friend std::istream& operator>>(std::istream& in, ModularType& num) {
    typename common_type<typename ModularType::Type, int64_t>::type x;
    in >> x;
    num.val = ModularType::normalize(x);
    return in;
  }

 private:
  Type val;
};

using ModType4 = int;
struct MyMod4 { static ModType4 value; };
ModType4 MyMod4::value;
using Num4 = ModularType<MyMod4>;

int main() {
  int n, m;
  cin >> n >> m >> MyMod4::value;
  vector<Num4> fact = {1};
  vector<Num4> inv_fact = {1};
  auto C = [&](int x, int y) {
    int sz = max(x, y);
    while ((int)fact.size() <= sz) {
      fact.push_back(fact.back() * (int)fact.size());
      inv_fact.push_back(1 / fact.back());
    }
    if (y < 0 || y > x) return Num4(0);
    return fact[x] * inv_fact[y] * inv_fact[x - y];
  };
  vector<Num4> ways_arr(m + 1, 0), ways_count(m + 1, 0);
  ways_count[0] = 1;
  for (int i = 1; i <= m; ++i) {
    for (int j = 0; j < i; ++j) {
      int l = j, r = i - 1 - j;
      ways_arr[i] += ways_count[l] * ways_count[r] * C(l + r, l) * Num4(l + r + 2);
    }
    for (int j = 0; j < i; ++j) {
      int l = j, r = i - 1 - j;
      Num4 add = (Num4(l) * (l + 1) + Num4(r) * (r + 1)) / 2;
      ways_count[i] += ways_count[l] * ways_count[r] * C(l + r, l) * add;
    }
  }
  vector<vector<Num4>> dp(n + 1, vector<Num4>(m + 1, 0));
  vector<vector<Num4>> ways_dp(n + 1, vector<Num4>(m + 1, 0));
  ways_dp[0][0] = 1;
  for (int i = 1; i <= n; ++i) {
    for (int s = 0; s <= min(m, i); ++s) {
      if (s == i) {
        dp[i][s] = ways_count[s];
        continue;
      }
      for (int d = 1; d <= s + 1; ++d) {
        Num4 ft = dp[i - d][s + 1 - d];
        Num4 way = ways_dp[i - d][s + 1 - d];
        int add = d - 1;
        ways_dp[i][s] += way * ways_count[add] * C(s, add);
        dp[i][s] += (way * ways_count[add] + ways_dp[i - d][s + 1 - d] * ft) * C(s, add);
      }
    }
  }
  cout << dp[n][m];
  return 0;
}
